package nl.rene.tools;

/** Sjablonen voor de tekens van de strook; gemaakt door tools/mrz/MrzSjablonen.java (niet met de hand wijzigen).
 *  Per teken (volgorde Mrz.ALPHABET) 3 varianten (gewoon, dikker, dunner) van 12×18 vakjes, 0–f = aandeel inkt. Gemeten op OCR-B (ISO 1073-2). */
final class MrzGlyphs {
    private MrzGlyphs(){ }
    static final int VARIANTS=3;
    static final String DATA="";
    private static double[][] cache;
    static synchronized double[][] templates(){
        if(cache!=null)return cache;int n=MrzOcr.GW*MrzOcr.GH,count=Mrz.ALPHABET.length()*VARIANTS;double[][] t=new double[count][n];
        for(int i=0;i<count&&(i+1)*n<=DATA.length();i++)for(int j=0;j<n;j++)t[i][j]=Character.digit(DATA.charAt(i*n+j),16)/15.0;
        return cache=t;
    }
}
